"""One native Geometry Nodes mesh program for prepared intersection records.

Python constructs these loops once. Their iteration counts, quad dimensions,
curve controls, profiles and connectivity references all come from the input
record geometry. No fixture identity or precomputed surface mesh is consumed.
"""
from .backend_runtime import V, rm
from . import backend_weld as chart_weld
from . import oblique


def spine(g, patches, pieces, index, t, *, max_pieces=3):
    """A collapsed half-profile sector contributes its exact plateau boundary."""
    original=rm.bezier(g,patches,index,t)
    boundary=rm.outer(g,patches,pieces,index,t,max_pieces=max_pieces)
    plateau=rm.read(g,patches,'plateau_edge',index,'BOOLEAN')
    return [_choose(g,plateau,b,a) for a,b in zip(original,boundary)]


def _choose(g, test, yes, no, kind='FLOAT'):
    node = g.node('GeometryNodeSwitch', 'Select record interpretation')
    node.input_type = kind
    g.bind(test, node.inputs['Switch'])
    g.bind(yes, node.inputs['True'])
    g.bind(no, node.inputs['False'])
    return V(g, node.outputs['Output'])


def _bounded(g, value):
    return g.math('MINIMUM', g.math('MAXIMUM', value, 0.), 1.)


def _equal(g, first, second):
    node = g.node('ShaderNodeMath', 'Exact record tag comparison')
    node.operation = 'COMPARE'
    g.bind(first, node.inputs[0])
    g.bind(second, node.inputs[1])
    node.inputs[2].default_value = 0.
    return V(g, node.outputs[0])


def _repeat(g, count, label):
    g.section(label)
    ri = g.node('GeometryNodeRepeatInput', label + ' input')
    ro = g.node('GeometryNodeRepeatOutput', label + ' output')
    ri.pair_with_output(ro)
    g.bind(count, ri.inputs['Iterations'])
    return ri, ro, V(g, ri.outputs['Iteration'])


def _append(g, accumulated, piece):
    join = g.node('GeometryNodeJoinGeometry', 'Append directly generated quads')
    g.bind(accumulated, join.inputs['Geometry'])
    g.bind(piece, join.inputs['Geometry'])
    return V(g, join.outputs['Geometry'])


def _grid(g, nu, nv, label):
    grid = g.node('GeometryNodeMeshGrid', label)
    grid.inputs['Size X'].default_value = 1.
    grid.inputs['Size Y'].default_value = 1.
    g.bind(nu, grid.inputs['Vertices X'])
    g.bind(nv, grid.inputs['Vertices Y'])
    return V(g, grid.outputs['Mesh'])


def _patches(g, arms, patches, pieces, factor, grass, *, max_pieces=3):
    ri, ro, index = _repeat(g, rm.count(g, patches), 'Generate each strip or sector record')

    def patch(name, kind='FLOAT'):
        return rm.read(g, patches, name, index, kind)

    grid = _grid(g, patch('nu_base') * factor + 1.,
                 patch('nv_base') * factor + 1., 'Direct strip or sector quad grid')
    x, y, _ = g.separate(g.position())
    raw, v = _choose(g, patch('flip', 'BOOLEAN'), 1. - (x + .5), x + .5), y + .5
    u = rm.angular(g, patches, pieces, index, raw,max_pieces=max_pieces)

    # Both analytic interpretations are generic fields; the record's kind
    # selects the appropriate result before Set Position evaluates the grid.
    arm = patch('arm', 'INT')
    tangent = g.separate(rm.read(g, arms, 'tangent', arm, 'FLOAT_VECTOR'))
    right = g.separate(rm.read(g, arms, 'right', arm, 'FLOAT_VECTOR'))
    width = rm.read(g, arms, 'width', arm)
    station = patch('station0') + patch('station_span') * u
    q = patch('q0') + patch('q_span') * v
    shift = rm.read(g, arms, 'profile_shift', arm)
    side_coordinate = q * .5 * width - shift
    left = g.math('LESS_THAN', side_coordinate, 0.)
    halfwidth = _choose(g, left, rm.read(g, arms, 'left_half_width', arm),
                       rm.read(g, arms, 'right_half_width', arm))
    # Preserve the original normalized coordinate exactly for symmetric arms.
    # At a half-profile's crown the other half has zero width. Define q=0
    # there explicitly instead of depending on Math Divide's zero behaviour.
    profile_q = _choose(g, _equal(g, shift, 0.), q,
                        side_coordinate / g.math('MAXIMUM', halfwidth, 1e-12))
    plateau = _choose(g, left, rm.read(g, arms, 'left_plateau_fraction', arm),
                     rm.read(g, arms, 'right_plateau_fraction', arm))
    denominator = 1. - plateau
    origin = g.separate(rm.read(g, arms, 'origin', arm, 'FLOAT_VECTOR'))
    strip_xy = [origin[j] + station * tangent[j] + q * .5 * width * right[j] for j in (0, 1)]
    patch_grass = patch('grass', 'BOOLEAN')
    strip_flag = _choose(g, patch_grass, False,
                         g.math('GREATER_THAN', g.math('ABSOLUTE', q), .9999999), 'BOOLEAN')
    half=g.math('GREATER_THAN',g.math('ABSOLUTE',rm.read(g,arms,'half_profile',arm,'INT')),0.)
    strip_flag=_choose(g,half,g.math('GREATER_THAN',g.math('ABSOLUTE',profile_q),.9999999),strip_flag,'BOOLEAN')
    strip_plateau=half*g.math('LESS_THAN',g.math('ABSOLUTE',profile_q),1e-7)
    strip_phi = _choose(g, patch_grass, 1., rm.profile(g, plateau, g.math('ABSOLUTE', profile_q), denominator))
    tilted=rm.read(g,arms,'oblique',arm,'BOOLEAN')
    left_outer=oblique.edge_at(g,arms,arm,'left',station)
    right_outer=oblique.edge_at(g,arms,arm,'right',station)
    left_inner=oblique.edge_at(g,arms,arm,'left',station,inner=True)
    right_inner=oblique.edge_at(g,arms,arm,'right',station,inner=True)
    left_strip=g.math('LESS_THAN',patch('q0'),-.9999999)
    start=oblique.select(g,left_strip,left_outer,oblique.select(g,patch_grass,left_inner,right_inner))
    end=oblique.select(g,left_strip,left_inner,oblique.select(g,patch_grass,right_inner,right_outer))
    strip_xy=oblique.select(g,tilted,[(1.-v)*a+v*b for a,b in zip(start,end)],strip_xy)
    tilted_phi=_choose(g,patch_grass,1.,_choose(g,left_strip,1.-(1.-v)**2,1.-v*v))
    strip_phi=_choose(g,tilted,tilted_phi,strip_phi)

    first = rm.read(g, arms, 'left_plateau_fraction', patch('first_arm', 'INT'))
    second = rm.read(g, arms, 'right_plateau_fraction', patch('second_arm', 'INT'))
    first_denominator = 1. - first
    second_denominator = 1. - second
    w = u * u * u * (10. + u * (-15. + 6. * u))

    def plateau_sampling(plateau):
        """Pin a median edge to row N/4 without changing the analytic chart."""
        mapped = _choose(g, g.math('GREATER_THAN', v, .25),
                         plateau + (v - .25) * (1. - plateau) / .75,
                         4. * v * plateau)
        return _choose(g, g.math('GREATER_THAN', plateau, 0.), mapped, v)

    sampled_v = (1. - w) * plateau_sampling(first) + w * plateau_sampling(second)
    radial = _choose(g, _equal(g, patch('radial_mode', 'INT'), 1), sampled_v, v)
    # Boundary identity is topological. Interpolating two plateau maps can
    # round 1 down by multiple ulps and must never unpin an outer Grid row.
    sector_flag = g.math('GREATER_THAN', v, .9999999)
    radial = _choose(g, sector_flag, 1., radial)
    K = rm.bezier(g, patches, index, u)
    C = rm.outer(g, patches, pieces, index, u,max_pieces=max_pieces)
    sector_xy = [(1. - radial) * K[j] + radial * C[j] for j in (0, 1)]
    sector_phi = ((1. - w) * rm.profile(g, first, radial, first_denominator)
                  + w * rm.profile(g, second, radial, second_denominator))

    is_sector = _equal(g, patch('kind', 'INT'), 1)
    xy = [_choose(g, is_sector, a, b) for a, b in zip(sector_xy, strip_xy)]
    flag = _choose(g, is_sector, sector_flag, strip_flag, 'BOOLEAN')
    fraction = _choose(g, is_sector, sector_phi, strip_phi)
    phi = _choose(g, flag, 0., _bounded(g, fraction))
    geometry = g.store(grid, 'outer_boundary', flag, 'POINT', 'BOOLEAN')
    geometry = g.store(geometry, 'plateau_boundary', (1.-is_sector)*strip_plateau, 'POINT', 'BOOLEAN')
    geometry = chart_weld.patch(g, geometry, patch, arms, raw, v, radial, profile_q, plateau, factor, rm)
    geometry = g.setpos(geometry, g.xyz(*xy, phi))
    geometry = g.store(geometry, 'surface_part', patch('surface_part', 'INT'), 'FACE', 'INT')

    # A Geometry Switch leaves the false input empty. This retains original
    # patch ordering while allowing one group to serve pavement and grass.
    selected = g.node('GeometryNodeSwitch', 'Output requested pavement or grass patches')
    selected.input_type = 'GEOMETRY'
    g.bind(_equal(g, patch_grass, grass)*(1.-is_sector*patch('plateau_edge','BOOLEAN')), selected.inputs['Switch'])
    g.bind(geometry, selected.inputs['True'])
    g.bind(_append(g, ri.outputs['Geometry'], selected.outputs['Output']), ro.inputs['Geometry'])
    return V(g, ro.outputs['Geometry'])


def _center(g, patches, pieces, header, factor, grass, *, max_pieces=3):
    # Compact sector order is the cyclic order of the prepared K boundary.
    kind = g.node('GeometryNodeInputNamedAttribute', 'Retain sector records for cyclic center')
    kind.data_type = 'INT'
    kind.inputs['Name'].default_value = 'kind'
    separate = g.node('GeometryNodeSeparateGeometry', 'Compact cyclic sector records')
    separate.domain = 'POINT'
    g.bind(patches, separate.inputs['Geometry'])
    g.bind(_equal(g, V(g, kind.outputs['Attribute']), 1), separate.inputs['Selection'])
    sectors = V(g, separate.outputs['Selection'])
    count = _choose(g, grass, 0, rm.count(g, sectors), 'INT')
    ri, ro, index = _repeat(g, count, 'Generate direct Coons quad block for each mouth')
    prev = rm.read(g, sectors, 'prev_sector_index', index, 'INT')
    center = g.separate(rm.read(g, header, 'hub', 0, 'FLOAT_VECTOR'))
    grid_count = (rm.read(g, sectors, 'nu_base', index) / 2.) * factor + 1.
    grid = _grid(g, grid_count, grid_count, 'Direct center quad grid')
    x, y, _ = g.separate(g.position())
    u, v = y + .5, .5 - x  # Quarter-turn indexing preserves native quad winding.

    def K(which, raw):
        return spine(g, sectors, pieces, which,
                     rm.angular(g, sectors, pieces, which, raw,max_pieces=max_pieces),
                     max_pieces=max_pieces)

    next_curve, prev_curve = K(index, .5 * u), K(prev, 1. - .5 * v)
    next_mid, prev_mid = K(index, .5), K(prev, .5)
    mouth = g.separate(rm.read(g, sectors, 'K0', index, 'FLOAT_VECTOR'))
    xy = [(1. - v) * next_curve[j] + (1. - u) * prev_curve[j]
          - (1. - u) * (1. - v) * mouth[j] + u * v * center[j] for j in (0, 1)]
    u_hi, v_hi = g.math('GREATER_THAN', u, .9999999), g.math('GREATER_THAN', v, .9999999)
    u_lo, v_lo = g.math('LESS_THAN', u, .0000001), g.math('LESS_THAN', v, .0000001)

    def replace(test, replacement, current):
        return [_choose(g, test, a, b) for a, b in zip(replacement, current)]

    # Both copies of an internal seam use identical arithmetic. Boundary
    # samples bypass Coons cancellation; the mouth reproduces the old average.
    next_seam = [(1. - v) * next_mid[j] + v * center[j] for j in (0, 1)]
    prev_seam = [(1. - u) * prev_mid[j] + u * center[j] for j in (0, 1)]
    xy = replace(u_hi, next_seam, xy)
    xy = replace(v_hi, prev_seam, xy)
    xy = replace(u_lo, prev_curve, xy)
    xy = replace(v_lo, next_curve, xy)
    xy = replace(u_lo * v_lo, [(next_curve[j] + prev_curve[j]) * .5 for j in (0, 1)], xy)
    geometry = chart_weld.center(g, grid, sectors, index, prev, factor, u, v, rm)
    plateau=g.math('MAXIMUM',v_lo*rm.read(g,sectors,'plateau_edge',index,'BOOLEAN'),
                            u_lo*rm.read(g,sectors,'plateau_edge',prev,'BOOLEAN'))
    geometry=g.store(geometry,'plateau_boundary',plateau,'POINT','BOOLEAN')
    geometry = g.setpos(geometry, g.xyz(*xy, 1.))
    g.bind(_append(g, ri.outputs['Geometry'], geometry), ro.inputs['Geometry'])
    geometry = V(g, ro.outputs['Geometry'])
    geometry = g.store(geometry, 'outer_boundary', False, 'POINT', 'BOOLEAN')
    return g.store(geometry, 'surface_part', -1, 'FACE', 'INT')


def build_geometry(g, arms, patches, pieces, header, factor, grass, *, max_pieces=3):
    """Generate joined quads from generic prepared record geometry sockets.

    ``patches`` omits retired core patches and preserves their original
    ``surface_part`` IDs. ``grass`` is a runtime Boolean socket. The returned
    geometry is flat, carrying ``original_phi`` for downstream height fields.
    """
    retained = _patches(g, arms, patches, pieces, factor, grass,max_pieces=max_pieces)
    center = _center(g, patches, pieces, header, factor, grass,max_pieces=max_pieces)
    g.section('Join directly generated quad patches and preserve height fraction')
    geometry = chart_weld.weld(g, _append(g, retained, center))
    x, y, phi = g.separate(g.position())
    geometry = g.store(geometry, 'original_phi', phi, 'POINT', 'FLOAT')
    geometry = g.setpos(geometry, g.xyz(x, y, 0.))
    g.g['center_construction'] = 'Direct mouth-centered Coons quad grids from cyclic sector records'
    g.g['center_grid_quarter_turn'] = True
    g.g['mesh_program'] = 'Generic runtime record Repeat loops; no fixture dispatch or baked surface meshes'
    return geometry
